# apt.map — logical name -> real Debian/Ubuntu package(s).
# Only rows where the name actually differs from the logical name (§1); anything
# not listed passes through unchanged.

build = build-essential
dev-headers = libssl-dev pkg-config
fd = fd-find

# Native-first (§1a G6): prefer the distro package so it updates via apt; fall
# back to a downloaded binary / install script only on releases that lack it.
# Availability was checked per release; a row exists ONLY where native is absent.
#
#             lsd      starship   fastfetch
#   bullseye  none     none       none        (Debian 11)
#   bookworm  native   none       none        (Debian 12)
#   trixie    native   native     native      (Debian 13)
#   jammy     none     none       none        (Ubuntu 22.04)
#   noble     native   none       none        (Ubuntu 24.04)
#   resolute  native   native     native      (Ubuntu 26.04)

# bullseye (Debian 11) has dpkg 1.20, which can't read modern zstd-compressed
# .debs -> use the release tarball binary (-> /usr/local/bin) there instead.
lsd@bullseye = source:provide_lsd_tarball
lsd@jammy    = source:provide_lsd_deb

fastfetch@bullseye = source:provide_fastfetch_tarball
fastfetch@bookworm = source:provide_fastfetch_deb
fastfetch@jammy    = source:provide_fastfetch_deb
fastfetch@noble    = source:provide_fastfetch_deb

starship@bullseye = script:https://starship.rs/install.sh --yes
starship@bookworm = script:https://starship.rs/install.sh --yes
starship@jammy    = script:https://starship.rs/install.sh --yes
starship@noble    = script:https://starship.rs/install.sh --yes

# Native name differences (Debian/Ubuntu).
go = golang
docker = docker.io
serie = cargo:serie          # not packaged on Debian/Ubuntu

# gh + btop are native on every release EXCEPT Debian 11 (bullseye) -> upstream
# release tarball there (bullseye's old dpkg can't take modern .debs anyway).
gh@bullseye   = source:provide_gh_tarball
btop@bullseye = source:provide_btop_tarball

# zig is native only on Ubuntu 25.10 (resolute); Debian + older Ubuntu build from
# the official ziglang.org tarball. ghostty likewise: native on resolute, else
# built from source (heavy). Build-dep name splits for the ghostty source path.
zig = source:provide_zig
zig@resolute = zig
# ghostty: native on 25.10 (resolute); community .deb on the releases the
# ghostty-ubuntu installer supports (Ubuntu 24.04 noble, Debian 13 trixie); Zig
# source build on the rest (jammy/bullseye/bookworm - no community binary).
ghostty = source:provide_ghostty
ghostty@resolute = ghostty
ghostty@noble = source:provide_ghostty_deb
ghostty@trixie = source:provide_ghostty_deb
xz = xz-utils
gtk4-dev = libgtk-4-dev
libadwaita-dev = libadwaita-1-dev
amneziavpn = source:provide_amneziavpn

